--
-- Table structure for table `races`
--

DROP TABLE IF EXISTS `races`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `races` (
  `raceId` int NOT NULL,
  `year` int NOT NULL,
  `round` int NOT NULL,
  `circuitId` int NOT NULL,
  `name` varchar(29) NOT NULL,
  `date` date NOT NULL,
  `time` varchar(8) DEFAULT NULL,
  `url` varchar(63) NOT NULL,
  `fp1_date` varchar(10) DEFAULT NULL,
  `fp1_time` varchar(8) DEFAULT NULL,
  `fp2_date` varchar(10) DEFAULT NULL,
  `fp2_time` varchar(8) DEFAULT NULL,
  `fp3_date` varchar(10) DEFAULT NULL,
  `fp3_time` varchar(8) DEFAULT NULL,
  `quali_date` varchar(10) DEFAULT NULL,
  `quali_time` varchar(8) DEFAULT NULL,
  `sprint_date` varchar(10) DEFAULT NULL,
  `sprint_time` varchar(8) DEFAULT NULL,
  PRIMARY KEY (`raceId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

